-- A 2-stage pipelined 8×8 multiplier. Stage 1 forms two partial products
-- (a × low nibble of b, a × high nibble); stage 2 adds them. One result
-- per cycle, two cycles of latency.
xblue module mkMul2;
  input Bool reset;
  input Bool in_valid;
  input Bit#(8) in_a;
  input Bit#(8) in_b;

  Reg#(Bool)     v1 <- mkReg(0);
  Reg#(Bit#(16)) lo <- mkReg(0);
  Reg#(Bit#(16)) hi <- mkReg(0);
  Reg#(Bool)     v2 <- mkReg(0);
  Reg#(Bit#(16)) p  <- mkReg(0);

  Bit#(16) a16 = zeroExtend(in_a);
  Bit#(16) bl  = zeroExtend(in_b[3:0]);
  Bit#(16) bh  = zeroExtend(in_b[7:4]);

  method Bool     out_valid = v2;
  method Bit#(16) out_p     = p;

  -- the later stage runs first in the cycle, so it reads stage 1's old
  -- contents before stage 1 overwrites them: a real pipeline register
  rule stage2;
    v2 <= v1;
    p <= lo + (hi << 4);
  endrule

  rule stage1;
    v1 <= in_valid;
    lo <= a16 * bl;
    hi <= a16 * bh;
  endrule

  rule clear (reset);
    v1 <= False;
    v2 <= False;
  endrule

  schedule stage2 ≫ stage1 ≫ clear;
endmodule

-- ---------------------------------------------------------------- reasoning
open XBlue

structure Regs where
  v1 : BitVec 1
  lo : BitVec 16
  hi : BitVec 16
  v2 : BitVec 1
  p : BitVec 16

/-- The registers after one clock cycle of the design itself. -/
def next (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) : Regs :=
  let r := (mkMul2.design.cycle (.cons reset (.cons valid (.cons a (.cons b .nil))))
              (.cons s.v1 (.cons s.lo (.cons s.hi (.cons s.v2 (.cons s.p .nil)))))).regs
  ⟨r.get mkMul2.v1, r.get mkMul2.lo, r.get mkMul2.hi, r.get mkMul2.v2, r.get mkMul2.p⟩

/-- The cycle as a story, latest stage first. `stage2` reads what stage 1 held
    at the start of the cycle; then `stage1` overwrites it. -/
def spec (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) : Regs :=
  -- stage2
  let v2 := s.v1
  let p  := s.lo + (s.hi <<< 4)
  -- stage1
  let v1 := valid
  let lo := a.zeroExtend 16 * (b.extractLsb' 0 4).zeroExtend 16
  let hi := a.zeroExtend 16 * (b.extractLsb' 4 4).zeroExtend 16
  -- clear
  ⟨if reset = 1#1 then 0#1 else v1, lo, hi, if reset = 1#1 then 0#1 else v2, p⟩

theorem next_eq_spec (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) :
    next reset valid a b s = spec reset valid a b s := by
  obtain ⟨v1, lo, hi, v2, p⟩ := s
  simp [next, spec, mkMul2.design, Design.cycle, mkMul2.schedule, mkMul2.interfaces,
    mkMul2.rules.stage1, mkMul2.rules.stage2, mkMul2.rules.clear, mkMul2.values.a16,
    mkMul2.values.bl, mkMul2.values.bh, mkMul2.signature, Sched.run, Action.step,
    Action.fires, writesIf, State.write, State.cur, State.read, HList.set, HList.get,
    Expr.eval, Expr.binVal, Common.putR, Common.putW, Common.memAt,
    mkMul2.v1, mkMul2.lo, mkMul2.hi, mkMul2.v2, mkMul2.p, mkMul2.reset, mkMul2.in_valid,
    mkMul2.in_a, mkMul2.in_b, sliceWidth]

/-- Consequences, each read off the story. -/
theorem product_after_two_cycles (reset reset' valid valid' : BitVec 1) (a b a' b' : BitVec 8) (s : Regs) :
    (next reset' valid' a' b' (next reset valid a b s)).p = a.zeroExtend 16 * b.zeroExtend 16 := by
  rw [next_eq_spec, next_eq_spec]
  simp only [spec]
  -- b is its low nibble plus its high nibble shifted by 4; multiplication distributes
  have hb : b.zeroExtend 16 = (b.extractLsb' 0 4).zeroExtend 16 + ((b.extractLsb' 4 4).zeroExtend 16 <<< 4) := by
    revert b; decide
  rw [hb, BitVec.mul_add]
  simp only [BitVec.shiftLeft_eq_mul_twoPow, BitVec.mul_assoc]

theorem valid_after_two_cycles (valid valid' : BitVec 1) (a b a' b' : BitVec 8) (s : Regs) :
    (next 0#1 valid' a' b' (next 0#1 valid a b s)).v2 = valid := by
  rw [next_eq_spec, next_eq_spec]
  simp [spec]

