-- A 2-stage pipelined 8×8 multiplier. Stage 1 forms two partial products
-- (a × low nibble of b, a × high nibble); stage 2 adds them. One result
-- per cycle, two cycles of latency.
xblue module mkMul2;
  input Bool reset;
  input Bool in_valid;
  input Bit#(8) in_a;
  input Bit#(8) in_b;

  Reg#(Bool)     v1 <- mkReg(0);
  Reg#(Bit#(16)) lo <- mkReg(0);
  Reg#(Bit#(16)) hi <- mkReg(0);
  Reg#(Bool)     v2 <- mkReg(0);
  Reg#(Bit#(16)) p  <- mkReg(0);

  Bit#(16) a16 = zeroExtend(in_a);
  Bit#(16) bl  = zeroExtend(in_b[3:0]);
  Bit#(16) bh  = zeroExtend(in_b[7:4]);

  method Bool     out_valid = v2;
  method Bit#(16) out_p     = p;

  -- the later stage runs first in the cycle, so it reads stage 1's old
  -- contents before stage 1 overwrites them: a real pipeline register
  rule mul;
    v2 <= in_valid;
    p <= a16 * zeroExtend(in_b);
  endrule

  rule clear (reset);
    v1 <= False;
    v2 <= False;
  endrule

  schedule mul ≫ clear;
endmodule

-- ---------------------------------------------------------------- reasoning
open XBlue

structure Regs where
  v1 : BitVec 1
  lo : BitVec 16
  hi : BitVec 16
  v2 : BitVec 1
  p : BitVec 16

/-- The registers after one clock cycle of the design itself. -/
def next (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) : Regs :=
  let r := (mkMul2.design.cycle (.cons reset (.cons valid (.cons a (.cons b .nil))))
              (.cons s.v1 (.cons s.lo (.cons s.hi (.cons s.v2 (.cons s.p .nil)))))).regs
  ⟨r.get mkMul2.v1, r.get mkMul2.lo, r.get mkMul2.hi, r.get mkMul2.v2, r.get mkMul2.p⟩

/-- The cycle as a story: one rule computes the whole product. -/
def spec (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) : Regs :=
  ⟨if reset = 1#1 then 0#1 else s.v1, s.lo, s.hi, if reset = 1#1 then 0#1 else valid,
    a.zeroExtend 16 * b.zeroExtend 16⟩

theorem next_eq_spec (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) :
    next reset valid a b s = spec reset valid a b s := by
  obtain ⟨v1, lo, hi, v2, p⟩ := s
  simp [next, spec, mkMul2.design, Design.cycle, mkMul2.schedule, mkMul2.interfaces,
    mkMul2.rules.mul, mkMul2.rules.clear, mkMul2.values.a16, mkMul2.signature, Sched.run, Action.step,
    Action.fires, writesIf, State.write, State.cur, State.read, HList.set, HList.get,
    Expr.eval, Expr.binVal, Common.putR, Common.putW, Common.memAt,
    mkMul2.v1, mkMul2.lo, mkMul2.hi, mkMul2.v2, mkMul2.p, mkMul2.reset, mkMul2.in_valid,
    mkMul2.in_a, mkMul2.in_b]

/-- Consequences, each read off the story. -/
theorem product_after_one_cycle (reset valid : BitVec 1) (a b : BitVec 8) (s : Regs) :
    (next reset valid a b s).p = a.zeroExtend 16 * b.zeroExtend 16 := by
  rw [next_eq_spec]
  simp [spec]

